import {expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

// @spec specs/hal-engine-config-hooks/spec.md#7
it('releases a resource acquired before session initialization fails', async () => {
  const resources = new Set<ChatSession>();
  const session: ChatSession = {sessionId: 'failed-start', userId: 'user', entries: []};
  const failure = new Error('initialization failed after allocation');
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'You are HAL.'}),
    undefined,
    {
      hooks: {
        beforeSession: async current => {
          resources.add(current);
          throw failure;
        },
        afterSession: async current => {
          resources.delete(current);
        },
      },
    }
  );

  const rejection: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({originalError: rejection === failure, remainingResources: resources.size}).toEqual({
    originalError: true,
    remainingResources: 0,
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/chatOrchestrator.sessionCleanup.test.ts"
